    "part": "Part XVIII",
    "title": {
      "hi": "वित्तीय आपात के बारे में उपबंध (Financial Emergency)",
      "en": "Provisions as to financial emergency"
    },
    "description": {
      "hi": "यदि भारत या उसके किसी भाग की वित्तीय साख खतरे में हो। 2 माह के भीतर संसद के साधारण बहुमत से अनुमोदन। राष्ट्रपति सभी अधिकारियों व जजों के वेतन में कटौती का निर्देश दे सकता है। भारत में अब तक एक बार भी लागू नहीं हुआ। (अमेरिका से प्रेरित)।",
      "en": "Invoked when financial stability or credit of India is threatened. Simple majority approval within 2 months. Never proclaimed in India so far."
    },
    "isImportant": true,
    "partName": {
      "hi": "भाग 18: आपात उपबंध (Emergency Provisions)",
      "en": "Part XVIII: Emergency Provisions"
    }
