      "hi": "371: महाराष्ट्र व गुजरात; 371A: नागालैंड; 371B: असम; 371C: मणिपुर; 371D/E: आंध्र प्रदेश व तेलंगाना; 371F: सिक्किम; 371G: मिजोरम; 371H: अरुणाचल प्रदेश; 371-I: गोवा; 371J: कर्नाटक (कल्याण-कर्नाटक क्षेत्र)।",
